from pathlib import Path
p=Path(__file__).resolve().parents[1]/'app/src/App.tsx';s=p.read_text(encoding='utf-8')
s=s.replace("import {renderCard} from './render';", "import {renderCard} from './render';\nimport {Scene} from './Scene';\nimport {CompanionStudio,ActorControls} from './CompanionStudio';\nimport {Mailbox} from './Mailbox';\nimport {readCompanions} from './db';\nimport {defaultComposition,quirkNames,type Sticker,type PetTrip,type StoredLetter} from './companions';")
s=s.replace("type Tab='explore'|'collection'|'settings';", "type Tab='explore'|'collection'|'settings'|'companions'|'mailbox';")
s=s.replace('interface Draft{visit:Visit;', 'interface Draft{visit?:Visit;')
s=s.replace(" const upload=useRef", " const [companions,setCompanions]=useState<{assets:Sticker[];trips:PetTrip[];letters:StoredLetter[]}>({assets:[],trips:[],letters:[]});\n const [now,setNow]=useState(Date.now());const [collectionFilter,setCollectionFilter]=useState<'all'|'visit'|'pet'>('all');\n const upload=useRef")
s=s.replace('async function refresh(){setData(await readAll());}', 'async function refresh(){const [d,c]=await Promise.all([readAll(),readCompanions()]);setData(d);setCompanions(c);setNow(Date.now());}')
s=s.replace("Promise.all([readAll(),setting<Draft>('draft')]).then(([saved,d])", "Promise.all([readAll(),setting<Draft>('draft'),readCompanions()]).then(([saved,d,c])")
s=s.replace('setData(saved);setSavedDraft(d??null);', 'setData(saved);setSavedDraft(d??null);setCompanions(c);')
s=s.replace(" useEffect(()=>{if(!notice)return;", " useEffect(()=>{const tick=()=>setNow(Date.now());const timer=setInterval(tick,10000);document.addEventListener('visibilitychange',tick);return()=>{clearInterval(timer);document.removeEventListener('visibilitychange',tick);};},[]);\n useEffect(()=>{if(!notice)return;")
s=s.replace('edit(makeDraft(selected,source));', "const next=makeDraft(selected,source);next.card.actor=defaultComposition(await setting<string>('defaultActor')??'mira-stand-v1');edit(next);")
s=s.replace('renderCard(card);','renderCard(card,companions.assets);')
s=s.replace("setTab('collection');setNotice('这一刻", "setTab('collection');setCollectionFilter('all');setNotice('这一刻")
s=s.replace("backupFile.size>5_000_000)throw Error('备份超过 5 MB。')", "backupFile.size>40_000_000)throw Error('备份超过 40 MB。')")
s=s.replace("  {tab==='collection'", "  {tab==='companions'&&!selected&&<CompanionStudio assets={companions.assets} trips={companions.trips} now={now} onRefresh={refresh} onNotice={setNotice} onViewCards={()=>{setTab('collection');setCollectionFilter('pet');}}/>}\n  {tab==='mailbox'&&!selected&&<Mailbox cards={data.cards} assets={companions.assets} letters={companions.letters} now={now} onRefresh={refresh} onNotice={setNotice}/>}\n  {tab==='collection'")
s=s.replace("{[...data.cards].sort", "{data.cards.filter(c=>collectionFilter==='all'||(collectionFilter==='pet'?c.origin==='pet':c.origin!=='pet')).sort")
s=s.replace('<article className="memory-card" key={card.id}><Artwork place={p}/>', '<article className="memory-card" key={card.id}><Scene card={card} assets={companions.assets}/>')
s=s.replace("{visit?.source==='manual'?'手动记录':'定位到访'}", "{card.origin==='pet'?'宠物见闻':visit?.source==='manual'?'手动记录':'定位到访'}")
s=s.replace("{categories.find(c=>c.id===card.category)?.name}</span>", "{card.origin==='pet'?quirkNames[card.quirk??'normal']:categories.find(c=>c.id===card.category)?.name}</span>")
s=s.replace('<div className="memory-actions"><button', '<div className="memory-actions"><button')
s=s.replace('{data.cards.length} 张明信片 · {visited.size} 个到访地点</p></div>', '{data.cards.length} 张明信片 · {visited.size} 个本人到访地点</p></div><div className="collection-filters" aria-label="收藏分类">{([{id:\'all\',label:\'全部\'},{id:\'visit\',label:\'我的旅行\'},{id:\'pet\',label:\'宠物见闻\'}]as const).map(f=><button key={f.id} aria-pressed={collectionFilter===f.id} onClick={()=>setCollectionFilter(f.id)}>{f.label}</button>)}</div>')
s=s.replace("{id:'collection',label:'收藏',icon:BookOpen}", "{id:'companions',label:'旅伴',icon:MapPin},{id:'collection',label:'收藏',icon:BookOpen},{id:'mailbox',label:'信箱',icon:Mail}")
s=s.replace('<Artwork place={placeById(draft.card.placeId)}/>', '<Scene card={draft.card} assets={companions.assets}/>')
s=s.replace('<label>到访日期<input', '<ActorControls value={draft.card.actor} kind={draft.card.origin===\'pet\'?\'pet\':\'human\'} allowNone={draft.card.origin!==\'pet\'} assets={companions.assets} onChange={actor=>edit({...draft,card:{...draft.card,actor}})}/><label>记录日期<input')
s=s.replace("{draft.visit.source==='manual'?'手动记录':'定位到访'}", "{draft.card.origin==='pet'?'宠物见闻，不计入本人足迹':draft.visit?.source==='manual'?'手动记录':'定位到访'}")
s=s.replace('备份含记录和文字，不包含图片。恢复后可重新下载卡面。','备份包含记录、自定义角色和往来信件；内置卡面可重新下载。请妥善保管备份。')
s=s.replace('漫邮 · Melbourne 0.1.0','漫邮 · Melbourne 0.2.0')
s=s.replace('卡面由本地模型制作，尚在内容审核阶段。三个类别暂用不同版式，独立场景图会逐步补齐。','固定风景叠加角色贴图；内置六位旅人、两只宠物，每位两种动作。支持导入本地制作的透明角色。慢信由你自行用聊天软件转发。')
p.write_text(s,encoding='utf-8')
